using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class LineupPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--lineup-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated-v8.json";}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Lineup and physical garage native checks");DontDestroyOnLoad(g);g.AddComponent<LineupPlayerProbe>();}
 void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!yes){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string t,string s,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+t);}void Update(){if(deadline>0&&!failed&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Lineup native timeout");}
 IEnumerator Wait(Func<bool> f){while(!f())yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string file){yield return new WaitForSecondsRealtime(.4f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/"+file+".png");yield return new WaitForSecondsRealtime(.4f);Check(new FileInfo(folder+"/"+file+".png").Length>50000,"Actual nonblank player render: "+file);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>RivalRaceDirector.Instance?.Ready==true&&PhysicalGarage.Instance?.Ready==true);var director=RivalRaceDirector.Instance;var garage=PhysicalGarage.Instance;var car=director.Trial.vehicle;car.externalInput=true;car.commandedHandbrake=false;car.commandedPedal=0;var camera=Camera.main;var follow=camera.GetComponent<FinchChaseCamera>();Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);
 var source=GameObject.Find("D01 | PLAYER GARAGE / DIY");File.WriteAllLines(folder+"/site-children.txt",source.transform.Cast<Transform>().Select(t=>t.name+" active="+t.gameObject.activeSelf));Check(source.GetComponentsInChildren<Transform>(true).Any(t=>t.name.StartsWith("Building | ")&&!t.gameObject.activeSelf)&&source.GetComponentsInChildren<Transform>(true).Any(t=>t.name.Contains("foundation")&&t.gameObject.activeSelf),"Only D01 placeholder body disabled; original physical foundation retained");follow.enabled=false;camera.transform.position=garage.Building.TransformPoint(new Vector3(20,10,-24));camera.transform.LookAt(garage.Building.TransformPoint(new Vector3(0,1.6f,0)));yield return Capture("Physical_Garage_Exterior");Check(garage.Building.GetComponentsInChildren<BoxCollider>().Length>10,"Garage walls/roof/workbenches have physical colliders");car.ResetAt(garage.Building.TransformPoint(new Vector3(0,.35f,-11)),garage.Building.rotation);follow.enabled=true;follow.Snap();yield return new WaitForSecondsRealtime(.8f);car.commandedPedal=.32f;double end=Time.realtimeSinceStartupAsDouble+7;while(garage.Building.InverseTransformPoint(car.transform.position).z< -1&&Time.realtimeSinceStartupAsDouble<end)yield return null;car.commandedPedal=0;car.commandedServiceBrake=1;yield return Wait(()=>car.SpeedKph<2);Check(garage.InBay(car.transform.position),"Player physically drives through open doorway into garage bay");yield return Capture("Physical_Garage_DriveIn");var shop=FindAnyObjectByType<ExpandedWorkshop>();Check(shop.Open(),"Existing G workshop is usable inside physical garage");yield return Capture("Garage_Workshop_Interior");shop.Close();for(int i=0;i<80;i++)director.Trial.Store.Settle(Finish(director.Trial.Definition),out _);Check(director.OpenPanel(),"Stopped garage player opens fleet menu");director.OpenShowroom();yield return Capture("Car_Showroom_Coda");Check(GameObject.Find("Showroom model / visual only")?.GetComponentsInChildren<Collider>().Length==0,"Showroom preview is geometry only without duplicate physics");director.ClosePanel();
 var owned=new List<string>();foreach(var spec in VehicleLineup.All){int cash=director.Trial.Store.Profile.availableCredits;string id=Guid.NewGuid().ToString("N");director.Trial.Store.BuyVehicle(id,spec.id,spec.price);director.ApplyVehicle();owned.Add(director.Trial.Store.Profile.fleet.selectedId);Check(director.Trial.Store.Profile.availableCredits==cash-spec.price&&car.PowertrainCarId==spec.id&&car.Engine.definition.massKg==spec.mass,"Buying "+spec.name+" selects actual model/powertrain and exact price");Check(car.GetComponentsInChildren<WheelCollider>().Length==4&&Math.Abs(car.Wheels[0].transform.localPosition.z-spec.wheelBase/2)<.001,"Selected "+spec.name+" retains exactly four contacts at actual wheelbase");car.ResetAt(garage.Building.TransformPoint(new Vector3(0,.35f,-1)),garage.Building.rotation);car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(.8f);follow.enabled=false;camera.transform.position=car.transform.position+garage.Building.TransformDirection(new Vector3(4.8f,2.5f,6.5f));camera.transform.LookAt(car.transform.position+Vector3.up*.7f);yield return Capture(spec.id+"_Physical");Check(shop.Open(),"Paid "+spec.name+" opens model-specific workshop");shop.View.Reveal("induction_small_1");foreach(var part in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_small_1")))Check(shop.Install(part.id),"Actual "+spec.name+" installs matched "+part.id);Check(shop.Catalog.car.carId==spec.id&&car.Engine.definition.IsTurbo&&car.Engine.definition.displayBoostBar>0,"Matched "+spec.name+" curve/spool/boost telemetry apply");yield return Capture(spec.id+"_Garage");shop.Close();follow.enabled=true;}
 director.Trial.Store.SelectVehicle(Guid.NewGuid().ToString("N"),owned[0]);director.ApplyVehicle();Check(car.PowertrainCarId=="car_coda"&&director.Trial.Store.ActiveWorkshop.induction=="small","Switching owned cars restores coupe model and its independent turbo build");Check(new RaceProgressStore(director.Trial.Store.PathName,director.Trial.Definition).ActiveModelId=="car_coda","Purchased models and selection survive actual player save reload");car.ResetAt(director.Trial.Definition.checkpoints[0].Position+Vector3.up*.35f,Quaternion.LookRotation(director.Trial.Definition.checkpoints[0].Forward));yield return new WaitForSecondsRealtime(.7f);Check(director.OpenPanel(),"Can enter rival menu with newly owned coupe");director.SelectedRival="club";director.Pinks=true;director.StakeConfirmed=true;Check(director.StartRace()&&director.Race.Contract.playerModelId=="car_coda"&&director.Opponent.Car.PowertrainCarId=="car_coda","Rival contract and real spawned opponent preserve distinct coupe model");yield return Capture("New_Model_Pink_Stakes");Check(director.BeforeLeave(),"New-model pink forfeit commits safely");Check(FleetLedger.Find(director.Trial.Store.Profile.fleet,owned[0]).owner=="rival","New coupe title loss does not turn it back into Finch");director.ReturnToRoad();string saved=File.ReadAllText(director.Trial.Store.PathName);HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);Check(PhysicalGarage.Instance==null&&RivalRaceDirector.Instance==null,"Apex sandbox does not instantiate city garage/fleet systems");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==saved,"Apex test remains byte-isolated from paid multi-car fleet");Check(!failed,"Native garage/models run has no runtime errors");Application.Quit(0);}
}
}
